=A student is applying for the role: "{{ $json.target_role }}".

=== RESUME ===
{{ $('Extract Resume Text').item.json.text }}

=== TARGET JOB DESCRIPTION ===
{{ $('Extract JD Text').item.json.text }}

Analyze the resume against the target job description. Use the job_description_library tool to retrieve similar real job postings and ground your analysis of expected skills. Then produce the resume score, skill gaps, resume improvements, an interview preparation roadmap, and a personalized 3-month learning plan.

assignments.value:
={{ (function(){
  var r = $json.output || {};
  var name = $('Resume & JD Intake').item.json.student_name || 'there';
  var role = $('Resume & JD Intake').item.json.target_role || '';
  var esc = function(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
  var li = function(a){ return (Array.isArray(a)?a:[]).map(function(x){ return '<li>'+esc(x)+'</li>'; }).join(''); };
  var roadmap = (Array.isArray(r.interview_prep_roadmap)?r.interview_prep_roadmap:[]).map(function(s){ return '<div style="margin-bottom:10px;"><strong>'+esc(s.stage)+'</strong> - '+esc(s.focus)+'<ul>'+li(s.actions)+'</ul></div>'; }).join('');
  var plan = (Array.isArray(r.learning_plan_3_months)?r.learning_plan_3_months:[]).map(function(m){ return '<div style="margin-bottom:12px;"><strong>'+esc(m.month)+'</strong><br/>Goals:<ul>'+li(m.goals)+'</ul>Resources:<ul>'+li(m.resources)+'</ul><em>Milestone:</em> '+esc(m.milestone)+'</div>'; }).join('');
  var score = (r.resume_score!=null)?r.resume_score:'N/A';
  return '<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#222;">'
    + '<h1 style="color:#2b6cb0;">Resume &amp; Career Report</h1>'
    + '<p>Hi '+esc(name)+', here is your analysis for <strong>'+esc(role)+'</strong>.</p>'
    + '<div style="font-size:32px;font-weight:bold;color:#2f855a;">Resume Score: '+esc(score)+'/100</div>'
    + '<p>'+esc(r.score_rationale)+'</p>'
    + '<h2 style="color:#2b6cb0;">Strengths</h2><ul>'+li(r.strengths)+'</ul>'
    + '<h2 style="color:#c05621;">Missing Skills</h2><ul>'+li(r.missing_skills)+'</ul>'
    + '<h2 style="color:#2b6cb0;">Resume Improvements</h2><ul>'+li(r.resume_improvements)+'</ul>'
    + '<h2 style="color:#2b6cb0;">Interview Preparation Roadmap</h2>'+roadmap
    + '<h2 style="color:#2b6cb0;">Your 3-Month Learning Plan</h2>'+plan
    + '</div>';
}()) }}
